#!/usr/bin/env python3
"""
dead_loop_scan.py -- scan a SystemVerilog source file for loop constructs and
report the result as a single structured JSON document on stdout.

Usage:
    python3 dead_loop_scan.py <sv_file>

The scanner recognises the five SystemVerilog loop forms and reports, for each
one, its count and the 1-based line number(s) where the loop keyword starts:

    forever          -> intentional monitor/driver threads (contain event or
                        delay control), classified as "intentional".
    for (...)        -> counted loops, classified "bounded" when the header has
                        an init/condition/step triple, "dead_loop" for for(;;).
    while (...)      -> plain while loops; busy-wait polling loops are flagged
                        as "dead_loop_candidate".
    do ... while()   -> counted as a single "do" construct (also reports the
                        trailing while() line); flagged when it spins on an
                        external condition / watchdog that may never fire.
    repeat (...)     -> counted loops, always "bounded" (fixed iteration count).

A "dead loop" / "dead loop candidate" is a loop that may never terminate:
it either has no timing control at all (a combinational infinite loop) or it
busy-waits on an external condition that is not guaranteed to change.

Pure Python standard library -- no third-party dependencies.
"""

import json
import re
import sys

# ---------------------------------------------------------------------------
# comment / string blanking (preserves newlines so line numbers stay exact)
# ---------------------------------------------------------------------------

def blank_comments_and_strings(text):
    """Return `text` with // and block comments plus double-quoted strings
    replaced by spaces. Newlines are preserved, so line numbering is kept."""
    lines = text.split('\n')
    out_lines = []
    in_block = False
    for line in lines:
        chars = list(line)
        n = len(chars)
        i = 0
        while i < n:
            c = chars[i]
            if in_block:
                end = line.find('*/', i)
                if end == -1:
                    for k in range(i, n):
                        chars[k] = ' '
                    i = n
                else:
                    for k in range(i, end + 2):
                        chars[k] = ' '
                    i = end + 2
                    in_block = False
                continue
            if c == '"':
                j = i + 1
                while j < n:
                    if chars[j] == '\\':
                        j += 2
                        continue
                    if chars[j] == '"':
                        j += 1
                        break
                    j += 1
                for k in range(i, min(j, n)):
                    chars[k] = ' '
                i = j
                continue
            if c == '/' and i + 1 < n and chars[i + 1] == '/':
                for k in range(i, n):
                    chars[k] = ' '
                i = n
                continue
            if c == '/' and i + 1 < n and chars[i + 1] == '*':
                end = line.find('*/', i + 2)
                if end == -1:
                    for k in range(i, n):
                        chars[k] = ' '
                    in_block = True
                    i = n
                else:
                    for k in range(i, end + 2):
                        chars[k] = ' '
                    i = end + 2
                continue
            i += 1
        out_lines.append(''.join(chars))
    return '\n'.join(out_lines)


# ---------------------------------------------------------------------------
# regexes
# ---------------------------------------------------------------------------

RE_FOREVER = re.compile(r'\bforever\b')
RE_FOR     = re.compile(r'\bfor\s*\(')
RE_WHILE   = re.compile(r'\bwhile\b')
RE_DO      = re.compile(r'\bdo\b')
RE_REPEAT  = re.compile(r'\brepeat\s*\(')
RE_BEGIN   = re.compile(r'\bbegin\b')
RE_END     = re.compile(r'\bend\b')
