def _loop_offset(cleaned, line_starts, ln, kind):
    """Recover the character offset of the loop keyword on the given 1-based
    line (used to re-find the body)."""
    start = line_starts[ln - 1]
    end = line_starts[ln] if ln - 1 < len(line_starts) - 1 else len(cleaned)
    seg = cleaned[start:end]
    patterns = {
        'forever': RE_FOREVER,
        'for': RE_FOR,
        'while': RE_WHILE,
        'do': RE_DO,
        'repeat': RE_REPEAT,
    }
    m = patterns[kind].search(seg)
    if m:
        return start + m.start()
    return start


def main(argv):
    if len(argv) != 2:
        sys.stderr.write('usage: python3 dead_loop_scan.py <sv_file>\n')
        return 2
    path = argv[1]
    try:
        with open(path, 'r', encoding='utf-8', errors='replace') as fh:
            text = fh.read()
    except OSError as exc:
        sys.stderr.write('error: cannot read %s: %s\n' % (path, exc))
        return 1
